  const id = Number(req.params.id);
  if (!Number.isInteger(id)) {
    return res.status(404).json({ error: 'Product not found' });
  }

  const product = productRepository.findById(id);
  if (!product || !product.active) {
    return res.status(404).json({ error: 'Product not found' });
  }

